function Logo({light=false}:{light?:boolean}){return <span className={'brand '+(light?'brand-light':'')}><span className="brand-mark"><BookOpen size={24}/></span><span><strong>dtb<span>.</span></strong><small>DILIGENT TUTORS BUREAU</small></span></span>}
function Modal({title,children,close,wide=false}:{title:string;children:ReactNode;close:()=>void;wide?:boolean}){const r=useRef<HTMLDialogElement>(null);useEffect(()=>{r.current?.showModal();const p=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.body.style.overflow=p;r.current?.close()}},[]);return <dialog ref={r} className={'modal '+(wide?'wide-modal':'')} onCancel={e=>{e.preventDefault();close()}}><button className="icon-btn close" onClick={close} aria-label="Close"><X/></button><h2>{title}</h2>{children}</dialog>}
function Field({label,children,wide=false}:{label:string;children:ReactNode;wide?:boolean}){return <label className={'field '+(wide?'full':'')}><span>{label}</span>{children}</label>}
function Checks({label,name,values,selected=[]}:{label:string;name:string;values:readonly string[];selected?:string[]}){return <fieldset className="check-group full"><legend>{label}</legend>{values.map(v=><label key={v}><input name={name} type="checkbox" value={v} defaultChecked={selected.includes(v)}/>{v}</label>)}</fieldset>}
function Status({value}:{value:string}){return <span className={'badge '+(['Approved','Completed','Registered'].includes(value)?'green':['Declined','Closed'].includes(value)?'grey':'amber')}>{value}</span>}
const date=(s:string)=>new Date(s).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});
