 function messageBox(ownerMode=false){const threadId=ownerMode?thread:data.userId,items=data.messages.filter(m=>m.threadUserId===threadId);return <div className={'messaging-layout '+(ownerMode?'owner-messaging':'')}>{ownerMode&&<aside className="conversation-list"><h3>Your conversations</h3>{allPeople.length?allPeople.map(p=><button key={p.userId} className={thread===p.userId?'selected':''} onClick={()=>setThread(p.userId)}><span className="user-avatar">{name(p.userId).charAt(0)}</span><span><b>{name(p.userId)}</b><small>{data.registrations.filter(x=>x.userId===p.userId).map(x=>x.role==='learner'?'Learner':'Tutor').join(' · ')}</small></span></button>):<p>No members registered yet.</p>}</aside>}<div className="panel chat-panel"><div className="chat-heading"><span className="g-avatar">{ownerMode?name(threadId).charAt(0):'G'}</span><div><h3>{ownerMode?name(threadId):'G · Your learning coordinator'}</h3><p>Private DTB inbox · replies appear here</p></div><button className="icon-btn" onClick={refresh} aria-label="Refresh messages"><RefreshCw size={16}/></button></div><div className="chat-messages" aria-label="Conversation">{items.length?items.map(m=><div key={m.id} className={'message-bubble '+((ownerMode?m.fromOwner==='yes':m.fromOwner==='no')?'sent':'received')}><b>{m.fromOwner==='yes'?'G':ownerMode?name(threadId):'You'}</b><p>{m.body}</p><small>{date(m.createdAt)}</small></div>):<div className="chat-empty"><MessageCircle size={32}/><h3>A conversation can change everything.</h3><p>{ownerMode?'Choose a registered learner or tutor and send a personal update.':'Ask about your request, share a learning update, or tell G what you need help with.'}</p></div>}</div><form className="compose" onSubmit={async e=>{e.preventDefault();const f=e.currentTarget;if(await act({action:'message',threadUserId:threadId,body:new FormData(f).get('body')},'Message sent in your DTB inbox.'))f.reset()}}><label className="sr-only" htmlFor="message-body">Your message</label><textarea id="message-body" name="body" required minLength={1} maxLength={3000} rows={2} placeholder={ownerMode?'Write a personal update…':'Write a message to G…'} disabled={!threadId||saving}/><button className="btn" disabled={!threadId||saving}><Send size={16}/><span>{saving?'Sending…':'Send'}</span></button></form><small className="chat-footnote">Messages stay inside DTB. Email, SMS and WhatsApp notifications are not connected.</small></div></div>}
 const resources=<div className="resource-list"><a href="/resources/algebra-practice.pdf" download><span className="resource-icon blue"><FileText/></span><span><b>Algebra foundations</b><small>Practice worksheet · answers included</small></span><Download size={17}/></a><a href="/resources/study-planner.pdf" download><span className="resource-icon green"><FileText/></span><span><b>Your weekly study planner</b><small>A little structure, a little progress</small></span><Download size={17}/></a></div>;
